<script lang="ts">
  import { untrack } from 'svelte';
  import { facade } from '../bus/gameFacade.js';
  import { game } from '../../gameManager.js';
  import {
    PROF_CHEN_DEFAULT_TOPIC_ID,
    PROF_CHEN_TOPICS,
    type ProfChenLocale,
    type ProfChenTopic,
    type ProfChenTopicId,
  } from '../data/profChenWikiContent.ts';
  import { uiText } from '../ui/i18n.ts';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import { playGameSfx } from '../audio/audioDirector.ts';
  import { searchProfChenFaqs } from '../lib/profChenWikiSearch.ts';

  const { trackGameLanguage } = useGameLanguageTick();

  function resolveLocale(): ProfChenLocale {
    trackGameLanguage();
    const normalized = game && typeof game.normalizeLanguage === 'function'
      ? game.normalizeLanguage(game.language)
      : String(game?.language || 'fr').toLowerCase();
    return normalized.startsWith('en') ? 'en' : 'fr';
  }

  function modalT(key: string, fallback: string, vars: Record<string, string | number> = {}): string {
    trackGameLanguage();
    return uiText(key, fallback, vars, game);
  }

  function findTopic(topicId: string): ProfChenTopic {
    return PROF_CHEN_TOPICS.find((topic) => topic.id === topicId) ?? PROF_CHEN_TOPICS[0];
  }

  const initialTopic = findTopic(PROF_CHEN_DEFAULT_TOPIC_ID);
  let selectedTopicId = $state<ProfChenTopicId>(initialTopic.id as ProfChenTopicId);
  let openFaqId = $state(initialTopic.faqs[0]?.id ?? '');
  let searchQuery = $state('');
  let searchInput: HTMLInputElement | undefined;

  let locale = $derived(resolveLocale());
  let titleLabel = $derived(modalT('modal.profChenTitle', 'Les conseils du Prof Chen'));
  let introLabel = $derived(modalT('modal.profChenIntro', 'Hey Prof Chen, je veux en savoir plus sur'));
  let closeLabel = $derived(modalT('modal.profChenClose', 'Fermer les conseils'));
  let selectedTopic = $derived(findTopic(selectedTopicId));
  let isSearching = $derived(searchQuery.trim().length > 0);
  let displayedFaqs = $derived(isSearching
    ? searchProfChenFaqs(PROF_CHEN_TOPICS, searchQuery, locale)
    : selectedTopic.faqs.map((faq) => ({ topic: selectedTopic, faq })));
  let searchLabel = $derived(modalT('modal.profChenSearchLabel', 'Rechercher un conseil'));
  let searchPlaceholder = $derived(modalT('modal.profChenSearchPlaceholder', 'Pokérus, œufs, prestige…'));
  let searchHint = $derived(modalT('modal.profChenSearchHint', 'Recherche dans toutes les rubriques.'));
  let searchClearLabel = $derived(modalT('modal.profChenSearchClear', 'Effacer la recherche'));
  let searchEmptyLabel = $derived(modalT('modal.profChenSearchEmpty', 'Aucun conseil trouvé. Essaie un autre mot-clé.'));
  let searchResultsLabel = $derived(modalT(
    displayedFaqs.length === 1 ? 'modal.profChenSearchResultOne' : 'modal.profChenSearchResultOther',
    displayedFaqs.length === 1 ? '{count} résultat dans toutes les rubriques' : '{count} résultats dans toutes les rubriques',
    { count: displayedFaqs.length },
  ));

  $effect(() => {
    const results = displayedFaqs;
    // Only a changed result set should open a fallback; manually closing an answer stays possible.
    untrack(() => {
      if (!results.some(({ faq }) => faq.id === openFaqId)) {
        openFaqId = results[0]?.faq.id ?? '';
      }
    });
  });

  function closeModal() {
    facade.dispatch({ type: 'CLOSE_MODAL', modalId: 'profChenWikiModal' });
  }

  function onTopicChange(e: Event) {
    const nextId = (e.target as HTMLSelectElement).value;
    const nextTopic = findTopic(nextId);
    selectedTopicId = nextTopic.id as ProfChenTopicId;
    searchQuery = '';
    openFaqId = nextTopic.faqs[0]?.id ?? '';
  }

  function clearSearch() {
    searchQuery = '';
    openFaqId = selectedTopic.faqs[0]?.id ?? '';
    searchInput?.focus();
  }

  function keepNativeActionKey(event: KeyboardEvent) {
    // The document's data-action keyboard handler would otherwise activate the modal shell.
    if (event.key === 'Enter' || event.key === ' ') event.stopPropagation();
  }

  function toggleFaq(faqId: string) {
    const closing = openFaqId === faqId;
    openFaqId = closing ? '' : faqId;
    playGameSfx(closing ? 'fold' : 'unfold');
  }
</script>

<div
  class="stats-content js-modal-content farming-metrics-modal-content prof-chen-modal-shell"
  data-action="stopPropagation"
  data-action-stop
>
  <div class="stats-header prof-chen-modal-header">
    <div class="prof-chen-title-wrap">
      <img
        src="img/prof_chen.png"
        class="prof-chen-title-sprite"
        alt=""
        aria-hidden="true"
        decoding="async"
      >
      <h2 id="profChenWikiTitleLabel">{titleLabel}</h2>
    </div>
    <button
      type="button"
      class="stats-close"
      data-action="closeProfChenWikiModal"
      title={closeLabel}
      aria-label={closeLabel}
    >&#10005;</button>
  </div>

  <div class="farming-metrics-body prof-chen-modal-body">
    <label class="prof-chen-question-row" for="profChenWikiTopicSelect">
      <span>{introLabel}</span>
      <select
        id="profChenWikiTopicSelect"
        class="prof-chen-topic-select"
        value={selectedTopicId}
        onchange={onTopicChange}
        onkeydown={keepNativeActionKey}
      >
        {#each PROF_CHEN_TOPICS as topic (topic.id)}
          <option value={topic.id}>{topic.label[locale]}</option>
        {/each}
      </select>
    </label>

    <div class="prof-chen-search-row">
      <label for="profChenWikiSearch">{searchLabel}</label>
      <div class="prof-chen-search-field">
        <input
          id="profChenWikiSearch"
          type="search"
          autocomplete="off"
          placeholder={searchPlaceholder}
          aria-controls="profChenWikiPanel"
          aria-describedby="profChenWikiSearchHint"
          bind:this={searchInput}
          bind:value={searchQuery}
          onkeydown={keepNativeActionKey}
        >
        {#if searchQuery}
          <button
            type="button"
            class="prof-chen-search-clear"
            aria-label={searchClearLabel}
            title={searchClearLabel}
            data-prof-chen-search-clear
            onclick={clearSearch}
            onkeydown={keepNativeActionKey}
          >×</button>
        {/if}
      </div>
      <p id="profChenWikiSearchHint" class="prof-chen-search-hint">{searchHint}</p>
    </div>

    {#if isSearching}
      <p class="prof-chen-search-status" role="status" data-prof-chen-search-status>{searchResultsLabel}</p>
    {/if}

    <section
      id="profChenWikiPanel"
      class="prof-chen-faq-list"
      data-prof-chen-panel
      data-topic-id={selectedTopic.id}
      aria-live={isSearching ? 'off' : 'polite'}
    >
      {#if isSearching && displayedFaqs.length === 0}
        <p class="prof-chen-search-empty" data-prof-chen-search-empty>{searchEmptyLabel}</p>
      {/if}
      {#each displayedFaqs as { topic, faq } (faq.id)}
        {@const isOpen = openFaqId === faq.id}
        <article class="prof-chen-faq-item" class:prof-chen-faq-item-open={isOpen}>
          {#if isSearching}
            <p class="prof-chen-faq-topic" data-prof-chen-topic>{topic.label[locale]}</p>
          {/if}
          <button
            type="button"
            class="prof-chen-faq-question"
            aria-expanded={isOpen}
            aria-controls={`profChenFaqAnswer-${faq.id}`}
            data-prof-chen-question
            onclick={() => toggleFaq(faq.id)}
            onkeydown={keepNativeActionKey}
          >
            <span>{faq.question[locale]}</span>
            <span class="prof-chen-faq-chevron" aria-hidden="true">{isOpen ? '-' : '+'}</span>
          </button>
          {#if isOpen}
            <p
              id={`profChenFaqAnswer-${faq.id}`}
              class="prof-chen-faq-answer"
              data-prof-chen-answer
            >{faq.answer[locale]}</p>
          {/if}
        </article>
      {/each}
    </section>
  </div>
</div>
