import type { ProfChenFaqItem, ProfChenLocale, ProfChenTopic } from '../data/profChenWikiContent.ts';

export interface ProfChenSearchResult {
  topic: ProfChenTopic;
  faq: ProfChenFaqItem;
}

function normalize(value: string): string {
  return value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/œ/g, 'oe').replace(/æ/g, 'ae');
}

/** Search localized topic labels, questions, and answers, preserving their display order. */
export function searchProfChenFaqs(
  topics: readonly ProfChenTopic[],
  query: string,
  locale: ProfChenLocale,
): ProfChenSearchResult[] {
  const terms = normalize(query).match(/[a-z0-9]+/g) ?? [];
  if (terms.length === 0) return [];

  const matches = terms.map(term => term === 'pp' || term === 'ct'
    ? (text: string) => new RegExp(`\\b${term}\\b`).test(text)
    : (text: string) => text.includes(term));
  const results: ProfChenSearchResult[] = [];
  for (const topic of topics) {
    for (const faq of topic.faqs) {
      const text = normalize(`${topic.label[locale]} ${faq.question[locale]} ${faq.answer[locale]}`);
      if (matches.every(match => match(text))) results.push({ topic, faq });
    }
  }
  return results;
}
